// ─────────────────────────────────────────────────────────────────────────────
// SHAPES & ATTRIBUTES WORKSHEET — a self-contained dashboard plugin.
//
// The dashboard loads this plugin by calling `ShapesWorksheet(dashboard)`
// with its configurations + layouts (see plugins/index.ts). Within this
// function the plugin describes:
//   - its SIDEBAR LABEL ('Shapes & Attributes', glyph '△') and which grades
//     offer it (a Year 1+ extension type);
//   - what happens when its label is CLICKED: its worksheet — generated by
//     the generator below — shows in the content area via the framework's
//     standard worksheet recipe (dashboard.createWorksheet).
//
// QUALITY-OVER-QUANTITY REDESIGN (T2V): six large single-column items instead
// of sixteen tiny two-column ones. Every item prints its shape figure(s) at
// the enlarged ShapeFigure size, and the page mixes OBSERVE items (count the
// sides/corners/faces of the printed shape) with ACT items (shade the named
// shape among the printed candidates) and JUSTIFY items (tick a statement
// true/false, then report a second shape's attribute) — all age-appropriate
// V8 recognition work with real printed area.
//
// Fully self-contained: the shape catalogue lives IN this plugin (duplicated
// deliberately — plugins never import from each other). Deleting this file
// and its line in plugins/index.ts removes the Shapes worksheet without
// affecting the framework or any other plugin.
// ─────────────────────────────────────────────────────────────────────────────

import type { Caps, DashboardFramework, DashboardPlugin, GradeConfig, RawProblem, Rng, WorksheetSpec } from '../../framework';
import { sampleUnique } from '../../framework';

// Shape catalogue for the shapes generator (V8-aligned 2-D + 3-D set: V9 keeps
// 3-D features for Year 3, but the app's Y2 already teaches V8-era content).
// `sides` counts STRAIGHT sides only (0 for curved-only shapes); `corners`
// is 2-D vertices; `flatFaces` is 3-D flat faces (0 for a sphere).
type ShapeDef = {
    name: string;
    sides: number;
    corners: number;
    flatFaces: number;
    curved: boolean;
    kind: '2d' | '3d';
};
const SHAPES: ShapeDef[] = [
    { name: 'circle', sides: 0, corners: 0, flatFaces: 0, curved: true, kind: '2d' },
    { name: 'oval', sides: 0, corners: 0, flatFaces: 0, curved: true, kind: '2d' },
    { name: 'triangle', sides: 3, corners: 3, flatFaces: 0, curved: false, kind: '2d' },
    { name: 'square', sides: 4, corners: 4, flatFaces: 0, curved: false, kind: '2d' },
    { name: 'rectangle', sides: 4, corners: 4, flatFaces: 0, curved: false, kind: '2d' },
    { name: 'hexagon', sides: 6, corners: 6, flatFaces: 0, curved: false, kind: '2d' },
    { name: 'cube', sides: 0, corners: 0, flatFaces: 6, curved: false, kind: '3d' },
    { name: 'prism', sides: 0, corners: 0, flatFaces: 6, curved: false, kind: '3d' },
    { name: 'pyramid', sides: 0, corners: 0, flatFaces: 4, curved: false, kind: '3d' },
    { name: 'cylinder', sides: 0, corners: 0, flatFaces: 2, curved: true, kind: '3d' },
    { name: 'cone', sides: 0, corners: 0, flatFaces: 1, curved: true, kind: '3d' },
    { name: 'sphere', sides: 0, corners: 0, flatFaces: 0, curved: true, kind: '3d' }
];
// Filter the catalogue down to the shapes the grade offers (names come from
// the grade's shapeSet); a grade with an empty set falls back to the FULL set
// so the generator can never run out of material.
function shapesFor(caps: Caps): ShapeDef[] {
    const avail = SHAPES.filter((s) => caps.shapeSet.includes(s.name));
    return avail.length >= 3 ? avail : SHAPES;
}
// "a"/"an" article for shape names (a circle, an oval).
function shapeArticle(name: string): string {
    return /^[aeiou]/i.test(name) ? 'an' : 'a';
}
// Sentence-case the name inside statements ("Square has 4 corners").
function shapeNameSentence(name: string): string {
    return name.charAt(0).toUpperCase() + name.slice(1);
}

// 2-D & 3-D shape recognition + attributes (V8 ACMMG159/174-175 era; V9 keeps
// the 2-D attribute questions for Y2 and moves 3-D features to Y3). Each
// question variant must pick from shapes the grade actually offers (shapeSet);
// if a variant's candidate pool is empty the generator degrades to the next
// simpler variant so Prep-sized shape sets still produce valid items.
//
// NON-REPEATING SAMPLING: the whole question passes through sampleUnique
// keyed on the printed prompt, so the same MC option list never prints twice
// in a row and the finite shape-bank space is spread evenly before repeats.
function generateShapes(rng: Rng, caps: Caps, count: number): RawProblem[] {
    const shapes = shapesFor(caps);
    const twoD = shapes.filter((s) => s.kind === '2d');
    const threeD = shapes.filter((s) => s.kind === '3d');
    return sampleUnique(
        count,
        () => {
            const r = rng.next();
            if (r < 0.18) {
                // "How many (straight) sides..." — only shapes that have them.
                // The figure draws the exact 2-D outline (framework/ShapeFigure.tsx);
                // the side count stays the private answer.
                const pool = twoD.filter((s) => s.sides > 0);
                const s = rng.pick(pool.length ? pool : twoD);
                return {
                    prompt: `Count the sides on the shape. How many sides does ${shapeArticle(s.name)} ${s.name} have? __`,
                    answer: `${s.sides}`,
                    shapes: [{ name: s.name, kind: '2d' }]
                };
            }
            if (r < 0.34) {
                // "How many corners..." — circles/ovals answer 0 (curved side).
                const s = rng.pick(twoD);
                return {
                    prompt: `Count the corners. How many corners does ${shapeArticle(s.name)} ${s.name} have? __`,
                    answer: `${s.corners}`,
                    shapes: [{ name: s.name, kind: '2d' }]
                };
            }
            if (r < 0.48 && threeD.length >= 3) {
                // "How many flat faces..." — 3-D objects only. The figure draws the
                // solid's line drawing; the face count stays the private answer.
                const s = rng.pick(threeD);
                return {
                    prompt: `Look at the solid. How many flat faces does ${shapeArticle(s.name)} ${s.name} have? __`,
                    answer: `${s.flatFaces}`,
                    shapes: [{ name: s.name, kind: '3d' }]
                };
            }
            if (r < 0.6 && threeD.length >= 3) {
                // SHADE ACT: shade the named solid among three printed
                // candidates. The answer is the named solid's name; the
                // student must recognise WHICH drawing it is. Shading acts on
                // the given candidates only — nothing here depends on a
                // previously computed answer.
                const answer = rng.pick(threeD);
                const others = threeD.filter((s) => s.name !== answer.name);
                if (others.length >= 2) {
                    const d1 = rng.pick(others);
                    const d2 = rng.pick(others.filter((s) => s.name !== d1.name));
                    const shown = [answer, d1, d2];
                    return {
                        prompt: `Shade the ${answer.name}.`,
                        answer: answer.name,
                        // Candidates in printed order, labelled under each
                        // drawing (framework/ShapeFigure.tsx).
                        shapes: shown.map((s) => ({ name: s.name, kind: '3d' as const }))
                    };
                }
                // Not enough solids to show candidates — fall through to the
                // plain corners count below so the item stays valid.
                const s = rng.pick(twoD);
                return {
                    prompt: `Count the corners. How many corners does ${shapeArticle(s.name)} ${s.name} have? __`,
                    answer: `${s.corners}`,
                    shapes: [{ name: s.name, kind: '2d' }]
                };
            }
            if (r < 0.72) {
                // JUSTIFY: tick the statement, then report a SECOND shape's
                // corner count. The statement is true for half the shapes and
                // off-by-one for the rest, so Yes/No is a real judgement; the
                // second blank keeps the item checkable end to end.
                const s = rng.pick(twoD);
                const lie = rng.next() < 0.5;
                const stated = lie ? s.corners + 1 : s.corners;
                const others = twoD.filter((x) => x.name !== s.name);
                const other = rng.pick(others.length ? others : twoD);
                return {
                    prompt: `Tick Yes or No: "${shapeNameSentence(s.name)} has ${stated} corners." __ Now count: how many corners does ${shapeArticle(other.name)} ${other.name} have? __`,
                    answer: `${lie ? 'No' : 'Yes'}, ${other.corners}`,
                    // Both printed shapes appear: the statement shape first,
                    // then the one to count.
                    shapes: [
                        { name: s.name, kind: '2d' as const },
                        { name: other.name, kind: '2d' as const }
                    ]
                };
            }
            if (r < 0.88) {
                // Multiple-choice on 2-D corners: the answer must be UNIQUE among
                // the shown options, so distractors share no corner count with it.
                let answer = rng.pick(twoD);
                let distractors = twoD.filter((s) => s.name !== answer.name && s.corners !== answer.corners);
                if (distractors.length < 2) {
                    // Deeper ambiguity (e.g. only circles+ovals offered) — fall
                    // back to a plain "how many corners" line instead.
                    answer = rng.pick(twoD);
                    return {
                        prompt: `Count the corners. How many corners does ${shapeArticle(answer.name)} ${answer.name} have? __`,
                        answer: `${answer.corners}`,
                        shapes: [{ name: answer.name, kind: '2d' }]
                    };
                }
                // Two distractors with different corner counts; the correct
                // shape sits at a random position in the printed list.
                const d1 = rng.pick(distractors);
                const d2 = rng.pick(distractors.filter((s) => s.name !== d1.name));
                const order = [answer, d1, d2];
                const at = rng.int(0, 2);
                const shown = [order[at], ...order.filter((s) => s !== order[at])];
                return {
                    prompt: `Which 2-D shape has ${answer.corners} corners? (${shown.map((s) => s.name).join(', ')}) __`,
                    answer: answer.name,
                    // Drawn in the prompt's option order, labelled under each
                    // outline (the labels keep the question unambiguous).
                    shapes: shown.map((s) => ({ name: s.name, kind: '2d' as const }))
                };
            }
            // 3-D "only flat faces" identification — shapes with NO curved surface (cube
            // / prism / pyramid); cones & cylinders have a curved side and a
            // sphere none at all, so flatFaces>0 is the WRONG filter.
            const allFlat = threeD.filter((s) => !s.curved);
            if (threeD.length >= 3 && allFlat.length >= 1) {
                const answer = rng.pick(allFlat);
                const others = threeD.filter((s) => s.name !== answer.name);
                // Distractors come from the CURVED-surface solids (cylinder /
                // cone / sphere) so the asked object is the UNIQUE all-flat
                // choice: Year 2's cube, prism AND pyramid are all all-flat,
                // so drawing distractors from the whole set would leave the
                // question with several correct candidates (T3 audit). A set
                // with fewer than two curved 3-D shapes falls back to the
                // original pool (the variant's own gate keeps it usable).
                const curved = threeD.filter((s) => s.curved);
                const pool = curved.length >= 2 ? curved : others;
                const d1 = rng.pick(pool);
                const d2 = rng.pick(pool.filter((s) => s.name !== d1.name));
                return {
                    prompt: `Which of these 3-D objects has only flat faces? (${[answer, d1, d2].map((s) => s.name).join(', ')}) __`,
                    answer: answer.name,
                    // Three labelled 3-D line drawings, in the prompt's order.
                    shapes: [
                        { name: answer.name, kind: '3d' as const },
                        { name: d1.name, kind: '3d' as const },
                        { name: d2.name, kind: '3d' as const }
                    ]
                };
            }
            const curved = twoD.filter((s) => s.curved);
            const answer = rng.pick(curved.length ? curved : twoD);
            return {
                prompt: `Does ${shapeArticle(answer.name)} ${answer.name} have a curved side? __`,
                answer: answer.curved ? 'Yes' : 'No',
                shapes: [{ name: answer.name, kind: '2d' as const }]
            };
        },
        (p) => p.prompt
    );
}

// The plugin's declarative spec (exported for its own tests).
export const shapesSpec: WorksheetSpec = {
    id: 'shapes',
    label: 'Shapes & Attributes',
    icon: '△',
    // Five large single-column items: each prints its shape figure(s) at full
    // size with room to count, shade and write — the old sixteen-up two-column
    // page left no usable area for any of that.
    // LAYOUT CAPACITY (T3M3): worst row = two prompt lines (2×21.6px) +
    // three 72px ShapeFigure cards (6+72+3+17px) = 141.2px; at 6/page the 1fr
    // row is 132.4px (overflow), at 5/page 163.6px (margin 22.4).
    // See plugins/layout-capacity.test.ts for the model.
    perPage: 5,
    singleColumn: true,
    offered: (grade: GradeConfig) => grade.available.includes('shapes'),
    scope: () => '2-D & 3-D shapes',
    generate: generateShapes
};

// The plugin: a function the dashboard calls with its framework bundle.
export function ShapesWorksheet(dashboard: DashboardFramework): DashboardPlugin {
    return dashboard.createWorksheet(shapesSpec);
}
